const pages = $input.all().map(item => item.json);

if (
  pages.length === 0 ||
  pages.some(p => !Array.isArray(p.results))
) {
  throw new Error("INVALID_CONTACT_PAGE_RESPONSE");
}

const contacts = pages.flatMap(p => p.results);
const lastPage = pages[pages.length - 1];

const nextCursor = lastPage.paging?.next?.after ?? null;
const ids = contacts.map(c => String(c.id));

if (new Set(ids).size !== ids.length) {
  throw new Error("DUPLICATE_CONTACTS_ACROSS_PAGES");
}

const fields = [
  "createdate",
  "hs_analytics_source",
  "hs_latest_source",
  "lifecyclestage",
  "hubspot_owner_id",
  "company",
  "industry",
  "hs_lead_status"
];

const coverage = {};

for (const field of fields) {
  const populated = contacts.filter(c => {
    const v = c.properties?.[field];
    return v !== null &&
      v !== undefined &&
      String(v).trim() !== "";
  }).length;

  coverage[field] = {
    populated_count: populated,
    missing_count: contacts.length - populated,
    coverage_pct: contacts.length
      ? Math.round(100 * populated / contacts.length)
      : null
  };
}

const distributions = {};

for (const field of [
  "hs_analytics_source",
  "hs_latest_source",
  "lifecyclestage",
  "industry"
]) {
  const counts = {};

  for (const contact of contacts) {
    const v = String(
      contact.properties?.[field] ?? "UNKNOWN"
    ).trim() || "UNKNOWN";

    counts[v] = (counts[v] ?? 0) + 1;
  }

  distributions[field] = counts;
}

const dates = contacts
  .map(c => c.properties?.createdate ?? c.createdAt)
  .filter(Boolean)
  .map(v => new Date(v))
  .filter(d => !Number.isNaN(d.getTime()))
  .sort((a, b) => a.getTime() - b.getTime());

const complete = nextCursor === null;

return [{
  json: {
    schema_version: "gtm_source_audit_v2",
    source: "hubspot_contacts",
    data_origin: "HUBSPOT_TEST_PORTAL",

    records: {
      total_returned: contacts.length,
      pages_fetched: pages.length,
      has_more_pages: !complete,
      all_contacts_loaded: complete,
      unique_contact_ids: ids.length
    },

    created_date_range: {
      earliest: dates.length
        ? dates[0].toISOString()
        : null,
      latest: dates.length
        ? dates[dates.length - 1].toISOString()
        : null
    },

    property_coverage: coverage,
    property_distributions: distributions,

    data_quality: {
      pagination_complete: complete,
      duplicate_contacts_detected: false,
      source_classification_verified: false,
      campaign_metrics_available: false
    },

    limitations: [
      "Contact properties may be incomplete or self-reported",
      "CRM source OFFLINE is not verified outreach attribution",
      "Contact records cannot establish demo outcomes",
      "Campaign data is required for outreach volume",
      ...(!complete
        ? ["Pagination stopped before all pages were loaded"]
        : [])
    ],

    crm_write_performed: false
  }
}];

