parameters.jsCode:
const pages = $input.all().map(item => item.json);

if (
  pages.length === 0 ||
  pages.some(p => !Array.isArray(p.results))
) {
  throw new Error("INVALID_MEETING_API_RESPONSE");
}

const meetings = pages.flatMap(p => p.results);
const lastPage = pages[pages.length - 1];

const nextCursor = lastPage.paging?.next?.after ?? null;
const complete = nextCursor === null;

const ids = meetings.map(m => String(m.id));

if (new Set(ids).size !== ids.length) {
  throw new Error("DUPLICATE_MEETING_IDS");
}

const fields = [
  "hs_meeting_title",
  "hs_meeting_start_time",
  "hs_meeting_end_time",
  "hs_meeting_outcome",
  "hs_timestamp",
  "hubspot_owner_id",
  "hs_activity_type"
];

const populated = value =>
  value !== null &&
  value !== undefined &&
  String(value).trim() !== "";

const coverage = {};

for (const field of fields) {
  const count = meetings.filter(m =>
    populated(m.properties?.[field])
  ).length;

  coverage[field] = {
    populated_count: count,
    missing_count: meetings.length - count,
    coverage_pct: meetings.length
      ? Math.round(100 * count / meetings.length)
      : null
  };
}

// Count outcomes without assuming every meeting is a demo.
const outcomes = {};

for (const meeting of meetings) {
  const outcome = String(
    meeting.properties?.hs_meeting_outcome ?? "UNKNOWN"
  ).trim().toUpperCase() || "UNKNOWN";

  outcomes[outcome] = (outcomes[outcome] ?? 0) + 1;
}

// Inspect contact association coverage.
let withContacts = 0;
let withoutContacts = 0;
let associationPayloadMissing = 0;
let totalLinksReturned = 0;

for (const meeting of meetings) {
  const entry = meeting.associations?.contacts;

  if (!entry || !Array.isArray(entry.results)) {
    associationPayloadMissing++;
    continue;
  }

  const linked = entry.results.length;
  totalLinksReturned += linked;

  if (linked > 0) {
    withContacts++;
  } else {
    withoutContacts++;
  }
}

// A title containing "demo" is only a candidate signal.
// This is NOT verified demo classification.
const demoTitleCandidates = meetings.filter(m =>
  /\b(demo|demonstration)\b/i.test(
    String(m.properties?.hs_meeting_title ?? "")
  )
).length;

function dateRange(field) {
  const values = meetings
    .map(m =>
      field === "createdAt"
        ? m.createdAt
        : m.properties?.[field]
    )
    .filter(populated)
    .map(v => new Date(v))
    .filter(d => !Number.isNaN(d.getTime()))
    .sort((a, b) => a - b);

  return {
    earliest: values.length
      ? values[0].toISOString()
      : null,
    latest: values.length
      ? values[values.length - 1].toISOString()
      : null
  };
}

return [{
  json: {
    schema_version: "gtm_meeting_source_audit_v1",
    source: "hubspot_meetings",
    data_origin: "HUBSPOT_TEST_PORTAL",

    records: {
      total_returned: meetings.length,
      pages_fetched: pages.length,
      all_meetings_loaded: complete,
      has_more_pages: !complete,
      unique_meeting_ids: ids.length
    },

    date_ranges: {
      created: dateRange("createdAt"),
      scheduled_start: dateRange("hs_meeting_start_time")
    },

    property_coverage: coverage,

    outcome_distribution: outcomes,

    associations: {
      with_contact_links: withContacts,
      without_contact_links: withoutContacts,
      association_payload_missing:
        associationPayloadMissing,
      total_contact_links_returned:
        totalLinksReturned
    },

    demo_classification: {
      title_contains_demo_count: demoTitleCandidates,
      verified_demo_count: null,
      classification_status:
        "NOT_YET_VERIFIED"
    },

    data_quality: {
      pagination_complete: complete,
      duplicate_meetings_detected: false,
      demo_outcome_mapping_verified: false,
      booking_cohorts_verified: false
    },

    limitations: [
      "Not every HubSpot meeting is a sales demo",
      "Scheduled meetings are not confirmed held demos",
      "Meeting outcomes may be missing or inaccurate",
      "Meeting creation time is not necessarily booking time",
      "Associated contact links do not prove attendance",
      "Contact association results may require additional pagination",
      ...(!complete
        ? ["Meeting pagination incomplete"]
        : [])
    ],

    crm_write_performed: false
  }
}];

const inputs = $input.all().map(i => i.json);

function getAudit(source) {
  const found = inputs.filter(x => x.source === source);
  if (found.length !== 1) {
    throw new Error(`EXPECTED_ONE_AUDIT:${source}`);
  }
  return found[0];
}

const contactAudit = getAudit("hubspot_contacts");
const meetingAudit = getAudit("hubspot_meetings");

// Read the source API responses from this same execution.
const contactPages = $("Read GTM Contacts")
  .all().map(i => i.json);

const meetingPages = $("Read GTM Meetings")
  .all().map(i => i.json);

function flatten(pages, source) {
  if (pages.some(p => !Array.isArray(p.results))) {
    throw new Error(`INVALID_SOURCE_PAGES:${source}`);
  }
  return pages.flatMap(p => p.results);
}

const rawContacts = flatten(contactPages, "contacts");
const rawMeetings = flatten(meetingPages, "meetings");

// Fail if our source audit and raw data disagree.
if (
  rawContacts.length !== contactAudit.records.total_returned ||
  rawMeetings.length !== meetingAudit.records.total_returned
) {
  throw new Error("SOURCE_AUDIT_COUNT_MISMATCH");
}

if (
  !contactAudit.records.all_contacts_loaded ||
  !meetingAudit.records.all_meetings_loaded
) {
  throw new Error("SOURCE_PAGINATION_INCOMPLETE");
}

function normalizeDate(raw) {
  if (raw === null || raw === undefined || raw === "") {
    return null;
  }

  const text = String(raw).trim();
  let d;

  if (/^\d{13}$/.test(text)) {
    d = new Date(Number(text));
  } else if (
    /^\d{4}-\d{2}-\d{2}T.*(?:Z|[+-]\d{2}:\d{2})$/i.test(text)
  ) {
    d = new Date(text);
  }

  return d && !Number.isNaN(d.getTime())
    ? d.toISOString()
    : null;
}

const issues = new Set();

// Normalized contact records.
const contacts = rawContacts.map(c => {
  const p = c.properties || {};
  const created = normalizeDate(p.createdate ?? c.createdAt);

  if ((p.createdate || c.createdAt) && !created) {
    issues.add("INVALID_CONTACT_CREATED_DATE");
  }

  return {
    source: "hubspot_contact",
    contact_id: String(c.id),
    created_at: created,
    company_text: p.company ?? null,
    company_verified: false,
    industry: p.industry ?? null,
    owner_id: p.hubspot_owner_id ?? null,
    lifecycle_stage: p.lifecyclestage ?? null,
    analytics_source: p.hs_analytics_source ?? null,
    latest_source: p.hs_latest_source ?? null
  };
});

const contactIds = new Set(
  contacts.map(c => c.contact_id)
);

if (contactIds.size !== contacts.length) {
  throw new Error("DUPLICATE_NORMALIZED_CONTACT_ID");
}

// Normalized meeting records.
const meetings = rawMeetings.map(m => {
  const p = m.properties || {};
  const association = m.associations?.contacts;

  const linksAvailable =
    Array.isArray(association?.results);

  const linkedIds = linksAvailable
    ? [...new Set(
        association.results
          .map(x => x?.id)
          .filter(x => x !== null && x !== undefined)
          .map(String)
      )]
    : [];

  if (!linksAvailable) {
    issues.add("CONTACT_ASSOCIATION_DATA_UNAVAILABLE");
  }

  if (association?.paging?.next || association?.has_more) {
    issues.add("CONTACT_ASSOCIATIONS_MAY_BE_PARTIAL");
  }

  const missingIds = linkedIds.filter(
    id => !contactIds.has(id)
  );

  if (missingIds.length) {
    issues.add("ASSOCIATED_CONTACT_NOT_IN_SNAPSHOT");
  }

  const outcome = String(
    p.hs_meeting_outcome ?? "UNKNOWN"
  ).trim().toUpperCase() || "UNKNOWN";

  const title = String(p.hs_meeting_title ?? "");

  const created = normalizeDate(
    p.hs_createdate ?? m.createdAt
  );

  const start = normalizeDate(p.hs_meeting_start_time);
  const end = normalizeDate(p.hs_meeting_end_time);

  if (
    (p.hs_meeting_start_time && !start) ||
    (p.hs_meeting_end_time && !end)
  ) {
    issues.add("INVALID_MEETING_DATE");
  }

  return {
    source: "hubspot_meeting",
    meeting_id: String(m.id),
    created_at: created,
    scheduled_start_at: start,
    scheduled_end_at: end,
    outcome_raw: outcome,
    owner_id: p.hubspot_owner_id ?? null,
    activity_type: p.hs_activity_type ?? null,

    contact_ids: linkedIds,
    missing_contact_ids: missingIds,
    association_lookup_complete:
      linksAvailable &&
      !association?.paging?.next &&
      association?.has_more !== true,

    // Text matching finds candidates, not confirmed demos.
    demo_title_candidate:
      /\b(demo|demonstration)\b/i.test(title),

    verified_sales_demo: false,
    held_demo_verified: false,

    // Created date is not guaranteed booking time.
    booking_timestamp_verified: false,
    booking_timestamp: null
  };
});

const meetingIds = new Set(
  meetings.map(m => m.meeting_id)
);

if (meetingIds.size !== meetings.length) {
  throw new Error("DUPLICATE_NORMALIZED_MEETING_ID");
}

const linkedContacts = new Set(
  meetings.flatMap(m =>
    m.contact_ids.filter(id => contactIds.has(id))
  )
);

const outcomes = {};
for (const m of meetings) {
  outcomes[m.outcome_raw] =
    (outcomes[m.outcome_raw] || 0) + 1;
}

if (meetings.some(m => m.outcome_raw === "UNKNOWN")) {
  issues.add("MEETING_OUTCOMES_MISSING");
}

issues.add("DEMO_CLASSIFICATION_NOT_VERIFIED");
issues.add("OUTREACH_CAMPAIGN_DATA_UNAVAILABLE");
issues.add("BOOKING_COHORTS_NOT_VERIFIED");

return [{
  json: {
    schema_version: "gtm_dataset_v1",
    data_origin: "HUBSPOT_TEST_PORTAL",
    analysis_status: "SOURCE_NORMALIZATION_ONLY",

    summary: {
      total_contacts: contacts.length,
      total_meetings: meetings.length,
      unique_contacts_with_meetings:
        linkedContacts.size,
      meetings_with_contact_links:
        meetings.filter(m => m.contact_ids.length > 0).length,
      demo_title_candidates:
        meetings.filter(m => m.demo_title_candidate).length,
      outcome_distribution: outcomes,
      verified_held_demos: null,
      booked_to_held_pct: null
    },

    data_quality: {
      contact_pagination_complete: true,
      meeting_pagination_complete: true,
      all_meeting_associations_complete:
        meetings.every(m => m.association_lookup_complete),
      issue_codes: [...issues].sort()
    },

    contacts,
    meetings,

    crm_write_performed: false
  }
}];

const SCENARIO = "outreach_growth_held_decline_v1";
const SEED = 2031;
const DAY = 24 * 60 * 60 * 1000;
const HOUR = 60 * 60 * 1000;

// These are synthetic test-fixture settings.
// The future analysis engine must NOT hardcode these results.
const cohorts = [
  {
    period: "baseline",
    segment: "targeted_labs",
    outreach: 200,
    replies: 54,
    booked: 27,
    held: 23,
    cancelled: 2,
    no_show: 1
  },
  {
    period: "baseline",
    segment: "broad_labs",
    outreach: 100,
    replies: 18,
    booked: 8,
    held: 6,
    cancelled: 1,
    no_show: 0
  },
  {
    period: "current",
    segment: "targeted_labs",
    outreach: 200,
    replies: 48,
    booked: 20,
    held: 15,
    cancelled: 2,
    no_show: 0
  },
  {
    period: "current",
    segment: "broad_labs",
    outreach: 400,
    replies: 40,
    booked: 14,
    held: 4,
    cancelled: 3,
    no_show: 0
  }
];

// Deterministic shuffle: same seed produces same records.
function permutation(n, seed) {
  const result = Array.from(
    { length: n },
    (_, i) => i
  );

  let state = seed >>> 0;

  for (let i = n - 1; i > 0; i--) {
    state = (
      Math.imul(1664525, state) + 1013904223
    ) >>> 0;

    const j = Math.floor(
      (state / 4294967296) * (i + 1)
    );

    [result[i], result[j]] =
      [result[j], result[i]];
  }

  return result;
}

const leads = [];
const events = [];
const iso = epoch => new Date(epoch).toISOString();

for (const [cohortIndex, c] of cohorts.entries()) {
  const counts = [
    c.outreach,
    c.replies,
    c.booked,
    c.held,
    c.cancelled,
    c.no_show
  ];

  if (
    !counts.every(Number.isSafeInteger) ||
    counts.some(x => x < 0) ||
    c.booked > c.replies ||
    c.replies > c.outreach ||
    c.held + c.cancelled + c.no_show > c.booked
  ) {
    throw new Error(
      `INVALID_SYNTHETIC_COHORT:${cohortIndex}`
    );
  }

  const shuffled = permutation(
    c.outreach,
    SEED + cohortIndex
  );

  const rank = Array(c.outreach);

  shuffled.forEach((leadIndex, position) => {
    rank[leadIndex] = position;
  });

  const periodStart = Date.parse(
    c.period === "baseline"
      ? "2026-08-01T09:00:00Z"
      : "2026-09-01T09:00:00Z"
  );

  for (let i = 0; i < c.outreach; i++) {
    const leadId =
      `synthetic_${c.period}_${c.segment}_` +
      String(i + 1).padStart(4, "0");

    const campaignId =
      `synthetic_campaign_${c.period}_${c.segment}`;

    const common = {
      schema_version: "gtm_event_v1",
      data_origin: "SYNTHETIC",
      lead_id: leadId,
      campaign_id: campaignId,
      period: c.period,
      channel: "outbound",
      segment: c.segment
    };

    function add(type, when, extras = {}) {
      events.push({
        ...common,
        event_id: `${leadId}:${type}`,
        event_type: type,
        occurred_at: iso(when),
        ...extras
      });
    }

    const sent =
      periodStart +
      ((i * 7 + cohortIndex * 3) % 20) * DAY +
      (i % 8) * HOUR;

    const reply = sent + DAY + (i % 4) * HOUR;
    const booking = reply + DAY;
    const scheduled = booking + 5 * DAY;

    const k = rank[i];

    leads.push({
      lead_id: leadId,
      data_origin: "SYNTHETIC",
      period: c.period,
      channel: "outbound",
      segment: c.segment,
      campaign_id: campaignId,
      first_outreach_at: iso(sent),
      icp_fit_verified: false
    });

    add("outreach_sent", sent);

    if (k >= c.replies) continue;

    add("reply_received", reply);

    if (k >= c.booked) continue;

    const meetingId =
      `synthetic_meeting_${leadId}`;

    add("demo_booked", booking, {
      meeting_id: meetingId,
      scheduled_for: iso(scheduled)
    });

    if (k < c.held) {
      add("demo_held", scheduled + HOUR, {
        meeting_id: meetingId
      });

    } else if (k < c.held + c.cancelled) {
      add("demo_cancelled", scheduled - DAY, {
        meeting_id: meetingId
      });

    } else if (
      k < c.held + c.cancelled + c.no_show
    ) {
      add("demo_no_show", scheduled + HOUR, {
        meeting_id: meetingId
      });
    }

    // No outcome event means UNKNOWN.
    // It does NOT mean the prospect was a no-show.
  }
}

// Derive summaries from generated events.
const eventTypes = [
  "outreach_sent",
  "reply_received",
  "demo_booked",
  "demo_held",
  "demo_cancelled",
  "demo_no_show"
];

const summaryByPeriod = {};

for (const period of ["baseline", "current"]) {
  const rows = events.filter(
    e => e.period === period
  );

  const count = type =>
    rows.filter(e => e.event_type === type).length;

  const counts = Object.fromEntries(
    eventTypes.map(t => [t, count(t)])
  );

  counts.demo_outcome_unknown =
    counts.demo_booked -
    counts.demo_held -
    counts.demo_cancelled -
    counts.demo_no_show;

  if (counts.demo_outcome_unknown < 0) {
    throw new Error(
      "INCONSISTENT_SYNTHETIC_MEETING_OUTCOMES"
    );
  }

  summaryByPeriod[period] = counts;
}

// Verify stable unique IDs.
if (
  new Set(leads.map(x => x.lead_id)).size !==
    leads.length ||
  new Set(events.map(x => x.event_id)).size !==
    events.length
) {
  throw new Error("DUPLICATE_SYNTHETIC_IDS");
}

return [{
  json: {
    schema_version: "gtm_synthetic_dataset_v1",
    data_origin: "SYNTHETIC",
    scenario: SCENARIO,
    seed: SEED,

    generated_from: "REPRODUCIBLE_TEST_FIXTURE",

    observation_cutoff:
      "2026-10-31T23:59:59Z",

    cohort_windows: {
      baseline:
        "2026-08-01 to 2026-08-31 (outreach cohort)",
      current:
        "2026-09-01 to 2026-09-30 (outreach cohort)"
    },

    summary: {
      leads: leads.length,
      events: events.length,
      by_period: summaryByPeriod
    },

    leads,
    events,

    limitations: [
      "Entire dataset is synthetic",
      "Constructed outcomes are not causal evidence",
      "ICP fit has not been verified",
      "Campaign delivery failures are not modeled",
      "Missing outcomes are not automatically no-shows"
    ],

    crm_write_performed: false
  }
}];

const dataset = $input.first().json;

if (
  $input.all().length !== 1 ||
  dataset.schema_version !== "gtm_synthetic_dataset_v1" ||
  dataset.data_origin !== "SYNTHETIC" ||
  !Array.isArray(dataset.leads) ||
  !Array.isArray(dataset.events)
) {
  throw new Error("EXPECTED_ONE_SYNTHETIC_GTM_DATASET");
}

const leads = dataset.leads;
const events = dataset.events;
const cutoffMs = Date.parse(dataset.observation_cutoff);

if (!Number.isFinite(cutoffMs)) {
  throw new Error("INVALID_OBSERVATION_CUTOFF");
}

const leadMap = new Map();

for (const lead of leads) {
  if (!lead.lead_id || leadMap.has(lead.lead_id)) {
    throw new Error("DUPLICATE_OR_MISSING_LEAD_ID");
  }

  leadMap.set(lead.lead_id, lead);
}

const allowedTypes = new Set([
  "outreach_sent",
  "reply_received",
  "demo_booked",
  "demo_held",
  "demo_cancelled",
  "demo_no_show"
]);

const outcomeTypes = new Set([
  "demo_held",
  "demo_cancelled",
  "demo_no_show"
]);

const eventIds = new Set();

// Validate source events before calculating any statistics.
for (const event of events) {
  const lead = leadMap.get(event.lead_id);

  if (
    !lead ||
    !event.event_id ||
    eventIds.has(event.event_id) ||
    event.schema_version !== "gtm_event_v1" ||
    event.data_origin !== "SYNTHETIC" ||
    !allowedTypes.has(event.event_type) ||
    event.period !== lead.period ||
    event.segment !== lead.segment ||
    event.channel !== lead.channel ||
    event.campaign_id !== lead.campaign_id
  ) {
    throw new Error(
      `INVALID_OR_DUPLICATE_EVENT:${event.event_id}`
    );
  }

  const timestamp = Date.parse(event.occurred_at);

  if (
    !Number.isFinite(timestamp) ||
    timestamp > cutoffMs
  ) {
    throw new Error(
      `EVENT_OUTSIDE_OBSERVATION_CUTOFF:${event.event_id}`
    );
  }

  eventIds.add(event.event_id);
}

const pct = (n, d) =>
  d ? Math.round((n / d) * 10000) / 100 : null;

const round = n => Math.round(n * 100) / 100;

// Derive funnel performance for any selected group of leads.
function summarize(groupLeads) {
  const leadIds = new Set(
    groupLeads.map(l => l.lead_id)
  );

  const groupEvents = events.filter(e =>
    leadIds.has(e.lead_id)
  );

  const sent = new Set();
  const replied = new Set();
  const bookedLeads = new Set();
  const heldLeads = new Set();

  const bookings = new Map();
  const outcomes = new Map();

  for (const e of groupEvents) {
    if (e.event_type === "outreach_sent") {
      sent.add(e.lead_id);
    }

    if (e.event_type === "reply_received") {
      replied.add(e.lead_id);
    }

    if (e.event_type === "demo_booked") {
      if (
        !e.meeting_id ||
        bookings.has(e.meeting_id) ||
        !Number.isFinite(Date.parse(e.scheduled_for))
      ) {
        throw new Error(
          `INVALID_DEMO_BOOKING:${e.event_id}`
        );
      }

      bookings.set(e.meeting_id, e);
      bookedLeads.add(e.lead_id);
    }

    if (outcomeTypes.has(e.event_type)) {
      if (
        !e.meeting_id ||
        outcomes.has(e.meeting_id)
      ) {
        throw new Error(
          `DUPLICATE_OR_MISSING_MEETING_OUTCOME:${e.event_id}`
        );
      }

      outcomes.set(e.meeting_id, e);

      if (e.event_type === "demo_held") {
        heldLeads.add(e.lead_id);
      }
    }
  }

  // This synthetic fixture models an outbound funnel.
  for (const id of replied) {
    if (!sent.has(id)) {
      throw new Error(`REPLY_WITHOUT_OUTREACH:${id}`);
    }
  }

  for (const id of bookedLeads) {
    if (!replied.has(id)) {
      throw new Error(`BOOKING_WITHOUT_REPLY:${id}`);
    }
  }

  // Every recorded outcome must belong to a valid booking.
  for (const [meetingId, outcome] of outcomes) {
    const booking = bookings.get(meetingId);

    if (
      !booking ||
      booking.lead_id !== outcome.lead_id ||
      Date.parse(outcome.occurred_at) <
        Date.parse(booking.occurred_at)
    ) {
      throw new Error(
        `OUTCOME_WITHOUT_VALID_BOOKING:${meetingId}`
      );
    }
  }

  const outcomeCounts = {
    held: 0,
    cancelled: 0,
    no_show: 0,
    unknown_matured: 0,
    pending_future: 0
  };

  for (const [meetingId, booking] of bookings) {
    const outcome = outcomes.get(meetingId);

    if (outcome?.event_type === "demo_held") {
      outcomeCounts.held++;
    } else if (outcome?.event_type === "demo_cancelled") {
      outcomeCounts.cancelled++;
    } else if (outcome?.event_type === "demo_no_show") {
      outcomeCounts.no_show++;
    } else if (
      Date.parse(booking.scheduled_for) > cutoffMs
    ) {
      outcomeCounts.pending_future++;
    } else {
      outcomeCounts.unknown_matured++;
    }
  }

  const maturedBookings =
    bookings.size - outcomeCounts.pending_future;

  return {
    counts: {
      leads_in_group: groupLeads.length,
      outreach_sent: sent.size,
      replies_received: replied.size,
      demos_booked: bookings.size,
      demos_held: outcomeCounts.held,
      demos_cancelled: outcomeCounts.cancelled,
      demos_no_show: outcomeCounts.no_show,
      demos_unknown_matured:
        outcomeCounts.unknown_matured,
      demos_pending_future:
        outcomeCounts.pending_future,
      unique_leads_with_bookings:
        bookedLeads.size,
      unique_leads_with_held_demos:
        heldLeads.size
    },

    rates: {
      reply_rate_pct:
        pct(replied.size, sent.size),

      booking_per_reply_pct:
        pct(bookedLeads.size, replied.size),

      held_per_matured_booking_pct:
        pct(outcomeCounts.held, maturedBookings),

      held_per_100_outreach:
        pct(outcomeCounts.held, sent.size)
    },

    measurement: {
      outreach_unit:
        "unique_leads_with_outreach_event",
      reply_unit:
        "unique_leads_with_reply_event",
      booking_unit:
        "unique_meetings",
      held_unit:
        "unique_meetings_with_explicit_held_event",
      denominator_for_held_rate:
        "bookings_whose_scheduled_time_is_at_or_before_cutoff",
      unknown_outcomes_are_no_shows: false
    }
  };
}

