const d = $input.first().json;

if (
  $input.all().length !== 1 ||
  d.schema_version !== "gtm_funnel_metrics_v1" ||
  !d.by_period?.baseline ||
  !d.by_period?.current ||
  !Array.isArray(d.by_segment)
) {
  throw new Error("INVALID_GTM_METRICS_INPUT");
}

const baseline = d.by_period.baseline;
const current = d.by_period.current;

const round = n => Math.round(n * 100) / 100;
const ratio = (n, den) => den > 0 ? n / den : null;

const factors = [
  {
    id: "outreach_volume",
    label: "Outreach volume",
    numerator: "outreach_sent",
    denominator: null
  },
  {
    id: "reply_conversion",
    label: "Reply / outreach",
    numerator: "replies_received",
    denominator: "outreach_sent"
  },
  {
    id: "booking_conversion",
    label: "Bookings / replies",
    numerator: "demos_booked",
    denominator: "replies_received"
  },
  {
    id: "held_conversion",
    label: "Recorded held / bookings",
    numerator: "demos_held",
    denominator: "demos_booked"
  }
];

function valuesFor(period) {
  return factors.map(f => {
    const n = period.counts[f.numerator];

    if (!Number.isSafeInteger(n) || n < 0) {
      throw new Error(`INVALID_COUNT:${f.numerator}`);
    }

    if (!f.denominator) return n;

    const den = period.counts[f.denominator];

    return ratio(n, den);
  });
}

const before = valuesFor(baseline);
const after = valuesFor(current);

const comparable =
  before.every(Number.isFinite) &&
  after.every(Number.isFinite) &&
  baseline.counts.demos_pending_future === 0 &&
  current.counts.demos_pending_future === 0;

const product = arr =>
  arr.reduce((result, value) => result * value, 1);

let attribution = {
  status: "NOT_EVALUABLE",
  factor_contributions: [],
  total_change: null
};

if (comparable) {
  const contributions = [0, 0, 0, 0];
  let permutations = 0;

  function calculate(order, remaining) {
    if (!remaining.length) {
      const state = [...before];

      for (const index of order) {
        const oldResult = product(state);
        state[index] = after[index];
        const newResult = product(state);

        contributions[index] += newResult - oldResult;
      }

      permutations++;
      return;
    }

    for (const index of remaining) {
      calculate(
        [...order, index],
        remaining.filter(x => x !== index)
      );
    }
  }

  calculate([], [0, 1, 2, 3]);

  const total =
    current.counts.demos_held -
    baseline.counts.demos_held;

  const averaged = contributions.map(
    x => x / permutations
  );

  if (
    Math.abs(
      averaged.reduce((a, b) => a + b, 0) - total
    ) > 0.000001
  ) {
    throw new Error("ATTRIBUTION_DOES_NOT_RECONCILE");
  }

  attribution = {
    status: "CALCULATED",
    method: "SHAPLEY_FACTOR_DECOMPOSITION",
    interpretation:
      "Order-independent mathematical attribution; not causal proof",

    factor_contributions: factors.map((f, i) => ({
      factor: f.id,
      baseline_factor: round(before[i]),
      current_factor: round(after[i]),
      contribution_to_held_demo_change:
        round(averaged[i])
    })),

    total_change: total,
    contribution_sum_unrounded:
      averaged.reduce((a, b) => a + b, 0)
  };
}

// Stage deterioration using unrounded source counts.
const stages = factors.slice(1).map((f, i) => {
  const b = before[i + 1];
  const c = after[i + 1];

  const change =
    Number.isFinite(b) && Number.isFinite(c)
      ? round(100 * (c - b))
      : null;

  return {
    stage: f.id,
    baseline_rate_pct:
      b === null ? null : round(100 * b),
    current_rate_pct:
      c === null ? null : round(100 * c),
    percentage_point_change: change,
    direction: change === null
      ? "unknown"
      : change < 0
        ? "declined"
        : change > 0
          ? "improved"
          : "unchanged"
  };
});

// Report bounds when matured meeting outcomes are missing.
function outcomeBounds(period) {
  const counts = period.counts;

  const matured =
    counts.demos_booked -
    counts.demos_pending_future;

  const held = counts.demos_held;
  const unknown = counts.demos_unknown_matured;

  if (matured <= 0) {
    return {
      lower_pct: null,
      upper_pct: null,
      matured_bookings: matured,
      unknown_outcomes: unknown
    };
  }

  return {
    lower_pct: round(100 * held / matured),
    upper_pct: round(
      100 * (held + unknown) / matured
    ),
    matured_bookings: matured,
    unknown_outcomes: unknown
  };
}

const baselineBounds = outcomeBounds(baseline);
const currentBounds = outcomeBounds(current);

const declineRobustToUnknown =
  baselineBounds.lower_pct !== null &&
  currentBounds.upper_pct !== null &&
  currentBounds.upper_pct <
    baselineBounds.lower_pct;

// Compare each segment between periods.
const segmentNames = [
  ...new Set(d.by_segment.map(s => s.segment))
].sort();

const segmentComparisons = segmentNames.map(segment => {
  const b = d.by_segment.find(
    s => s.period === "baseline" &&
      s.segment === segment
  );

  const c = d.by_segment.find(
    s => s.period === "current" &&
      s.segment === segment
  );

  if (!b || !c) {
    return {
      segment,
      comparable: false,
      reason: "MISSING_ONE_PERIOD"
    };
  }

  const heldChange =
    c.counts.demos_held - b.counts.demos_held;

  const yieldBefore = ratio(
    b.counts.demos_held,
    b.counts.outreach_sent
  );

  const yieldAfter = ratio(
    c.counts.demos_held,
    c.counts.outreach_sent
  );

  return {
    segment,
    comparable: true,
    baseline_outreach: b.counts.outreach_sent,
    current_outreach: c.counts.outreach_sent,
    baseline_held: b.counts.demos_held,
    current_held: c.counts.demos_held,
    held_demo_count_change: heldChange,

    baseline_held_per_100_outreach:
      yieldBefore === null
        ? null : round(100 * yieldBefore),

    current_held_per_100_outreach:
      yieldAfter === null
        ? null : round(100 * yieldAfter),

    yield_change_percentage_points:
      yieldBefore === null || yieldAfter === null
        ? null
        : round(100 * (yieldAfter - yieldBefore))
  };
});

const rankedDeteriorations = stages
  .filter(s => s.direction === "declined")
  .sort(
    (a, b) =>
      a.percentage_point_change -
      b.percentage_point_change
  )
  .map(s => s.stage);

const bottleneckAnalysis = {
  schema_version: "gtm_bottleneck_analysis_v1",
  data_origin: d.data_origin,
  scenario: d.scenario,

  observed_business_problem: {
    outreach_increased:
      current.counts.outreach_sent >
      baseline.counts.outreach_sent,

    held_demos_decreased:
      current.counts.demos_held <
      baseline.counts.demos_held,

    held_demo_count_change:
      current.counts.demos_held -
      baseline.counts.demos_held
  },

  funnel_stage_changes: stages,
  deteriorating_stages_ranked_by_pp:
    rankedDeteriorations,

  mathematical_attribution: attribution,

  meeting_outcome_uncertainty: {
    baseline: baselineBounds,
    current: currentBounds,
    recorded_held_rate_decline_robust_to_unknown_outcomes:
      declineRobustToUnknown
  },

  segment_comparisons: segmentComparisons,

  interpretation_boundaries: [
    "A numerical contribution is not a causal explanation",
    "Segment-level differences do not prove ICP mismatch",
    "Unknown outcomes are not classified as no-shows",
    "Prospect motives cannot be inferred from funnel counts",
    "Analysis uses synthetic data"
  ],

  causal_claim_established: false,
  automated_intervention_authorized: false
};

return [{
  json: {
    ...d,
    bottleneck_analysis: bottleneckAnalysis
  }
}];

const incoming = $input.first().json;
const evidence =
  $("Diagnose GTM Funnel Changes").first().json;

let ai = incoming.output ?? incoming;

if (typeof ai === "string") {
  try {
    ai = JSON.parse(ai);
  } catch {
    throw new Error("AI_OUTPUT_IS_NOT_JSON");
  }
}


//
// Normalize known AI metric-path abbreviations.
//
// This does NOT invent missing metrics or bypass
// validation. Every normalized path must still
// resolve to a real field in the evidence.
//

for (const h of ai.hypotheses ?? []) {
  for (const field of [
    "supporting_metric_keys",
    "counterevidence_metric_keys"
  ]) {
    if (!Array.isArray(h[field])) continue;

    h[field] = h[field].map(path => {
      if (typeof path !== "string") {
        return path;
      }

      // The AI occasionally omits the parent
      // object for segment comparisons.
      const diagnosticRoots = [
        "segment_comparisons",
        "meeting_outcome_uncertainty",
        "funnel_stage_changes",
        "mathematical_attribution",
        "observed_business_problem"
      ];

      const root = path.split(/[.[]/)[0];

      if (diagnosticRoots.includes(root)) {
        return `bottleneck_analysis.${path}`;
      }

      return path;
    });
  }
}


function requireCondition(ok, message) {
  if (!ok) throw new Error(message);
}

const nonEmpty = x =>
  typeof x === "string" && x.trim().length > 0;

const stringList = a =>
  Array.isArray(a) && a.every(nonEmpty);

// Verify the original deterministic evidence.
requireCondition(
  evidence.schema_version === "gtm_funnel_metrics_v1" &&
  evidence.data_origin === "SYNTHETIC" &&
  evidence.bottleneck_analysis?.schema_version ===
    "gtm_bottleneck_analysis_v1",
  "INVALID_REFERENCE_DATA"
);

// Validate AI schema and hard safety boundaries.
requireCondition(
  ai &&
  ai.schema_version === "gtm_hypotheses_v1" &&
  ai.data_origin === evidence.data_origin &&
  ai.causal_claim_established === false &&
  ai.crm_write_authorized === false,
  "INVALID_AI_HEADER_OR_SAFETY_FLAGS"
);

requireCondition(
  nonEmpty(ai.business_question) &&
  nonEmpty(ai.summary_of_observed_pattern) &&
  nonEmpty(ai.priority_investigation) &&
  stringList(ai.deliberately_not_automated) &&
  ai.deliberately_not_automated.length > 0 &&
  Array.isArray(ai.hypotheses) &&
  ai.hypotheses.length === 3,
  "INVALID_AI_OUTPUT_STRUCTURE"
);

// Resolve a metric path against the real JSON.
// Only literal properties and numeric array indices
// are accepted. No expressions or invented paths.
function validMetricPath(path) {
  if (
    !nonEmpty(path) ||
    path.length > 200 ||  
    !/^(?:by_period|by_segment|bottleneck_analysis|observed_signals|provenance)(?:\.[A-Za-z_][A-Za-z0-9_]*|\.\d+|\[\d+\])+$/.test(path)
  ) {
    return false;
  }

  let current = evidence;

  const parts = path
    .replace(/\[(\d+)\]/g, ".$1")
    .split(".");

  for (const key of parts) {
    if (
      current === null ||
      typeof current !== "object" ||
      !Object.prototype.hasOwnProperty.call(
        current, key
      )
    ) {
      return false;
    }

    current = current[key];
  }

  return current !== null && (
    (typeof current === "number" &&
      Number.isFinite(current)) ||
    typeof current === "boolean" ||
    typeof current === "string"
  );
}

const statuses = new Set([
  "PLAUSIBLE_UNVERIFIED",
  "NOT_EVALUABLE",
  "CONTRADICTED_BY_OBSERVATIONS"
]);

const ids = new Set();
let checkedReferences = 0;

for (const h of ai.hypotheses) {
  requireCondition(
    h &&
    nonEmpty(h.id) &&
    !ids.has(h.id) &&
    nonEmpty(h.claim) &&
    statuses.has(h.status) &&
    stringList(h.supporting_metric_keys) &&
    stringList(h.counterevidence_metric_keys) &&
    stringList(h.missing_evidence) &&
    h.missing_evidence.length > 0 &&
    nonEmpty(h.next_verification_step) &&
    h.automatic_intervention_allowed === false,
    `INVALID_HYPOTHESIS:${h?.id ?? "unknown"}`
  );

  ids.add(h.id);

  requireCondition(
    h.status === "NOT_EVALUABLE" ||
      h.supporting_metric_keys.length > 0,
    `HYPOTHESIS_MISSING_SUPPORT:${h.id}`
  );

  for (const key of [
    ...h.supporting_metric_keys,
    ...h.counterevidence_metric_keys
  ]) {
    requireCondition(
      validMetricPath(key),
      `INVALID_METRIC_REFERENCE:${h.id}:${key}`
    );

    checkedReferences++;
  }
}

// Keep the original metrics for the HTML report.
return [{
  json: {
    ...evidence,

    ai_hypotheses: ai,

    ai_validation: {
      status:
        "PASSED_STRUCTURAL_AND_REFERENCE_CHECKS",
      metric_references_checked:
        checkedReferences,

      // Valid references do not prove a
      // free-text business explanation.
      semantic_accuracy_verified: false,
      causal_claim_established: false,
      crm_write_authorized: false
    }
  }
}];
